class TrackedDynamicArray {
  constructor() {
    this.capacity = 1;
    this.length = 0;
    this.data = new Array(this.capacity);
    this.resizeCount = 0;
  }
  push(val) {
    if (this.length === this.capacity) {
      this.capacity *= 2;
      const newData = new Array(this.capacity);
      for (let i = 0; i < this.length; i++) newData[i] = this.data[i];
      this.data = newData;
      this.resizeCount++;
    }
    this.data[this.length++] = val;
  }
  get(i) {
    return this.data[i];
  }
}

function compareApproaches(n) {
  const d = new TrackedDynamicArray();
  for (let i = 0; i < n; i++) d.push(i);
  return { incrementalResizes: d.resizeCount, preallocatedResizes: 0 };
}

