function insertAtWithShiftCount(arr, index, value) {
  let shifts = 0;
  arr.push(undefined);
  for (let i = arr.length - 1; i > index; i--) {
    arr[i] = arr[i - 1];
    shifts++;
  }
  arr[index] = value;
  return shifts;
}

function deleteAtWithShiftCount(arr, index) {
  let shifts = 0;
  for (let i = index; i < arr.length - 1; i++) {
    arr[i] = arr[i + 1];
    shifts++;
  }
  arr.pop();
  return shifts;
}

function goodContains(arr, targets) {
  const set = new Set(arr);
  return targets.filter(t => set.has(t));
}

