function maxAreaBrute(heights) {
  let maxArea = 0;
  for (let i = 0; i < heights.length; i++) {
    for (let j = i + 1; j < heights.length; j++) {
      const area = Math.min(heights[i], heights[j]) * (j - i);
      maxArea = Math.max(maxArea, area);
    }
  }
  return maxArea;
}

function maxAreaOptimal(heights) {
  // PROOF: if heights[left] < heights[right], the container's height is
  // bounded by heights[left]. Keeping right fixed and moving left inward
  // can only decrease or keep the same width while height stays bounded
  // by the SAME or smaller value -- so no better answer exists with the
  // current left paired with any right <= current right. It is safe to
  // discard left and move it forward; the symmetric argument applies
  // when heights[right] is the shorter wall.
  let left = 0, right = heights.length - 1, maxArea = 0;
  while (left < right) {
    const area = Math.min(heights[left], heights[right]) * (right - left);
    maxArea = Math.max(maxArea, area);
    if (heights[left] < heights[right]) left++; else right--;
  }
  return maxArea;
}

function isPalindromeTwoPointer(s) {
  const cleaned = s.toLowerCase().replace(/[^a-z0-9]/g, '');
  let left = 0, right = cleaned.length - 1;
  while (left < right) {
    if (cleaned[left] !== cleaned[right]) return false;
    left++; right--;
  }
  return true;
}

