function buildStringSlow(chars) {
  let result = '';
  for (const c of chars) result += c;
  return result;
}

function buildStringFast(chars) {
  const parts = [];
  for (const c of chars) parts.push(c);
  return parts.join('');
}

function benchmarkStringBuilding(n) {
  const chars = Array.from({length: n}, () => 'x');
  const t1 = Date.now();
  buildStringSlow(chars);
  const slowMs = Date.now() - t1;
  const t2 = Date.now();
  buildStringFast(chars);
  const fastMs = Date.now() - t2;
  return { slowMs, fastMs };
}

